INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8de2-79fc-b442-a88cd6ce2f45'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Benjamin and Daniel have monthly allowances in the ratio 7 : 4. After each of them spends $50, the ratio of their remaining allowances becomes 5 : 2. Calculate Daniel''s allowance at the start.', '$100', 'Let Benjamin''s initial allowance be 7x and Daniel''s initial allowance be 4x. After spending $50 each, their remaining allowances are 7x - 50 and 4x - 50. Set up ratio: (7x - 50) / (4x - 50) = 5 / 2. Cross-multiply: 2(7x - 50) = 5(4x - 50) => 14x - 100 = 20x - 250 => 6x = 150 => x = 25. Daniel''s allowance = 4 * 25 = $100.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:13.026Z'::timestamptz, '2026-08-15T07:36:13.026Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8de7-7fc8-a4cc-433f7eecc779'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Given that 1 / (3^(k + 2)) = 3^4 + 3^4 + 3^4, find the value of k.', '-7', 'Simplify RHS: 3^4 + 3^4 + 3^4 = 3 * (3^4) = 3^5. Rewrite LHS using negative index: 1 / (3^(k + 2)) = 3^(-(k + 2)). Equating exponents: -(k + 2) = 5 => -k - 2 = 5 => -k = 7 => k = -7.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:13.031Z'::timestamptz, '2026-08-15T07:36:13.031Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c83d-7730-85f3-8f230ac0d1fa'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Calculate √((15.2²)/(1 - 0.046)), giving your answer correct to the nearest whole number.', '16', 'Evaluate √((15.2²)/(0.954)) = 15.56... Therefore, the answer to the nearest whole number is 16.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:39.931Z'::timestamptz, '2026-08-15T07:50:39.931Z'::timestamptz) ON CONFLICT (id) DO NOTHING;